CREATE TABLE document_control.sipoc_maps (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES core.organizations(id),
  record_number integer GENERATED ALWAYS AS IDENTITY UNIQUE, fields jsonb NOT NULL CHECK(jsonb_typeof(fields)='object'),
  status text NOT NULL DEFAULT 'Draft' CHECK(status IN ('Draft','Submitted','Approved','Returned')),
  version integer NOT NULL DEFAULT 1, revision integer NOT NULL DEFAULT 1, approved_revision integer,
  decision_notes text NOT NULL DEFAULT '', source_key text, source_payload jsonb,
  created_by_user_id uuid REFERENCES identity.users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE(organization_id,id), UNIQUE(organization_id,source_key)
);
CREATE TABLE document_control.sipoc_revisions (
  organization_id uuid NOT NULL, map_id uuid NOT NULL, revision integer NOT NULL,
  fields jsonb NOT NULL CHECK(jsonb_typeof(fields)='object'), owner_name text NOT NULL, approved_by_user_id uuid NOT NULL REFERENCES identity.users(id),
  approved_at timestamptz NOT NULL DEFAULT now(), notes text NOT NULL CHECK(length(trim(notes))>0),
  PRIMARY KEY(organization_id,map_id,revision), FOREIGN KEY(organization_id,map_id) REFERENCES document_control.sipoc_maps(organization_id,id)
);
ALTER TABLE document_control.sipoc_maps ADD FOREIGN KEY(organization_id,id,approved_revision) REFERENCES document_control.sipoc_revisions(organization_id,map_id,revision);
CREATE INDEX sipoc_register ON document_control.sipoc_maps(organization_id,record_number DESC);
CREATE FUNCTION document_control.sipoc_immutable_revision() RETURNS trigger LANGUAGE plpgsql AS $immutable$
BEGIN RAISE EXCEPTION 'Approved SIPOC revisions are immutable'; END $immutable$;
CREATE TRIGGER sipoc_immutable_revision BEFORE UPDATE OR DELETE ON document_control.sipoc_revisions FOR EACH ROW EXECUTE FUNCTION document_control.sipoc_immutable_revision();
GRANT SELECT,INSERT,UPDATE ON document_control.sipoc_maps TO mrmpl_web;
GRANT SELECT,INSERT ON document_control.sipoc_revisions TO mrmpl_web;
GRANT USAGE,SELECT ON SEQUENCE document_control.sipoc_maps_record_number_seq TO mrmpl_web;
GRANT SELECT ON document_control.sipoc_maps,document_control.sipoc_revisions TO mrmpl_reporting;
INSERT INTO identity.permissions(key,module,name,description) VALUES
 ('iso.sipoc.read','iso-document','View SIPOC process maps','View process boundaries, SIPOC elements, approved revisions and history.'),
 ('iso.sipoc.manage','iso-document','Prepare SIPOC process maps','Prepare drafts, assign process owners and submit maps for QA review.'),
 ('iso.sipoc.approve','iso-document','QA approve SIPOC process maps','Approve a submitted revision or return it with findings.');
INSERT INTO identity.role_permissions(role_id,permission_id)
SELECT role.id,permission.id FROM identity.roles role CROSS JOIN identity.permissions permission
WHERE permission.key='iso.sipoc.read'
 OR (role.key IN ('administrator','quality-assurance-hod') AND permission.key LIKE 'iso.sipoc.%')
 OR (role.key='department-manager' AND permission.key='iso.sipoc.manage') ON CONFLICT DO NOTHING;

